-- BESC Cloud DEV: sjvzrsmrtcxxtmaxigtn. Read-only catalogue inspection.
-- Includes schema code for the explicitly selected review functions, never tokens or business rows.
begin isolation level repeatable read read only;
set local statement_timeout = '30s';
select jsonb_build_object(
 'format','besc-foundation-effects-v1', 'checked_at_utc',clock_timestamp(),
 'read_only',current_setting('transaction_read_only'), 'postgres_version',current_setting('server_version'),
 'tables',(select jsonb_agg(jsonb_build_object('schema',n.nspname,'name',c.relname,'rls',c.relrowsecurity,'force_rls',c.relforcerowsecurity,
   'columns',(select jsonb_agg(jsonb_build_object('name',a.attname,'type',format_type(a.atttypid,a.atttypmod),'not_null',a.attnotnull,'identity',a.attidentity,'generated',a.attgenerated,'column_acl',a.attacl::text,'default',pg_get_expr(d.adbin,d.adrelid)) order by a.attnum) from pg_attribute a left join pg_attrdef d on d.adrelid=a.attrelid and d.adnum=a.attnum where a.attrelid=c.oid and a.attnum>0 and not a.attisdropped),
   'grants',(select jsonb_object_agg(r, jsonb_build_object('select',has_table_privilege(r,c.oid,'SELECT'),'insert',has_table_privilege(r,c.oid,'INSERT'),'update',has_table_privilege(r,c.oid,'UPDATE'),'delete',has_table_privilege(r,c.oid,'DELETE'),'truncate',has_table_privilege(r,c.oid,'TRUNCATE'),'references',has_table_privilege(r,c.oid,'REFERENCES'),'trigger',has_table_privilege(r,c.oid,'TRIGGER'))) from unnest(array['anon','authenticated','service_role']) r)) order by n.nspname,c.relname)
   from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname in('public','private') and c.relkind='r'),
 'constraints',(select jsonb_agg(jsonb_build_object('schema',n.nspname,'table',c.relname,'name',k.conname,'type',k.contype,'definition',pg_get_constraintdef(k.oid,true),'validated',k.convalidated,'deferrable',k.condeferrable,'deferred',k.condeferred) order by n.nspname,c.relname,k.conname) from pg_constraint k join pg_class c on c.oid=k.conrelid join pg_namespace n on n.oid=c.relnamespace where n.nspname in('public','private')),
 'indexes',(select jsonb_agg(jsonb_build_object('schema',n.nspname,'table',t.relname,'name',c.relname,'definition',pg_get_indexdef(c.oid),'valid',i.indisvalid,'ready',i.indisready) order by n.nspname,c.relname) from pg_index i join pg_class c on c.oid=i.indexrelid join pg_class t on t.oid=i.indrelid join pg_namespace n on n.oid=t.relnamespace where n.nspname in('public','private')),
 'triggers',(select jsonb_agg(jsonb_build_object('schema',n.nspname,'table',c.relname,'name',t.tgname,'definition',pg_get_triggerdef(t.oid,true),'enabled',t.tgenabled) order by n.nspname,c.relname,t.tgname) from pg_trigger t join pg_class c on c.oid=t.tgrelid join pg_namespace n on n.oid=c.relnamespace where not t.tgisinternal and (n.nspname in('public','private') or(n.nspname='auth' and t.tgname='on_auth_user_created'))),
 'policies',(select jsonb_agg(jsonb_build_object('schema',schemaname,'table',tablename,'name',policyname,'permissive',permissive,'roles',roles,'command',cmd,'using',qual,'check',with_check) order by schemaname,tablename,policyname) from pg_policies where schemaname in('public','private') or(schemaname='storage' and (policyname like '%avatar%' or policyname like '%proof%'))),
 'enums',(select jsonb_agg(jsonb_build_object('schema',n.nspname,'name',t.typname,'labels',(select jsonb_agg(e.enumlabel order by e.enumsortorder) from pg_enum e where e.enumtypid=t.oid)) order by n.nspname,t.typname) from pg_type t join pg_namespace n on n.oid=t.typnamespace where n.nspname in('public','private') and t.typtype='e'),
 'functions',(select jsonb_agg(jsonb_build_object('schema',n.nspname,'name',p.proname,'arguments',pg_get_function_identity_arguments(p.oid),'returns',pg_get_function_result(p.oid),'language',l.lanname,'owner',pg_get_userbyid(p.proowner),'security_definer',p.prosecdef,'settings',p.proconfig,'volatility',p.provolatile,'strict',p.proisstrict,'body_md5',md5(replace(p.prosrc,chr(13),'')),
   'anon_execute',has_function_privilege('anon',p.oid,'EXECUTE'),'authenticated_execute',has_function_privilege('authenticated',p.oid,'EXECUTE'),'service_role_execute',has_function_privilege('service_role',p.oid,'EXECUTE')) order by n.nspname,p.proname,pg_get_function_identity_arguments(p.oid)) from pg_proc p join pg_namespace n on n.oid=p.pronamespace join pg_language l on l.oid=p.prolang where n.nspname in('public','private') and p.prokind='f'),
 'views',(select jsonb_agg(jsonb_build_object('schema',n.nspname,'name',c.relname,'definition',pg_get_viewdef(c.oid,true),'options',c.reloptions,
   'grants',(select jsonb_object_agg(r,jsonb_build_object('select',has_table_privilege(r,c.oid,'SELECT'),'insert',has_table_privilege(r,c.oid,'INSERT'),'update',has_table_privilege(r,c.oid,'UPDATE'),'delete',has_table_privilege(r,c.oid,'DELETE'))) from unnest(array['anon','authenticated','service_role']) r)) order by n.nspname,c.relname) from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname in('public','private') and c.relkind='v'),
 'sequences',(select coalesce(jsonb_agg(jsonb_build_object('schema',n.nspname,'name',c.relname,'start',s.seqstart,'increment',s.seqincrement,'minimum',s.seqmin,'maximum',s.seqmax,'cache',s.seqcache,'cycle',s.seqcycle,
   'grants',(select jsonb_object_agg(r,jsonb_build_object('usage',has_sequence_privilege(r,c.oid,'USAGE'),'select',has_sequence_privilege(r,c.oid,'SELECT'),'update',has_sequence_privilege(r,c.oid,'UPDATE'))) from unnest(array['anon','authenticated','service_role']) r)) order by n.nspname,c.relname),'[]'::jsonb) from pg_sequence s join pg_class c on c.oid=s.seqrelid join pg_namespace n on n.oid=c.relnamespace where n.nspname in('public','private')),
 'platform_public_defaults',(select coalesce(jsonb_agg(jsonb_build_object('type',d.defaclobjtype,'acl',d.defaclacl::text) order by d.defaclobjtype),'[]'::jsonb) from pg_default_acl d join pg_namespace n on n.oid=d.defaclnamespace where n.nspname='public' and pg_get_userbyid(d.defaclrole)='postgres'),
 'schema_usage',(select jsonb_agg(jsonb_build_object('schema',n.nspname,'anon',has_schema_privilege('anon',n.oid,'USAGE'),'authenticated',has_schema_privilege('authenticated',n.oid,'USAGE'),'service_role',has_schema_privilege('service_role',n.oid,'USAGE')) order by n.nspname) from pg_namespace n where n.nspname in('public','private')),
 'review_bodies',(select jsonb_agg(jsonb_build_object('schema',n.nspname,'name',p.proname,'arguments',pg_get_function_identity_arguments(p.oid),'source',p.prosrc) order by n.nspname,p.proname) from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname in('public','private') and p.proname in('can_manage_discord_bot','discord_answers','discord_embed_valid','discord_type_valid','guard_community_document','discord_bot_operation','guard_event_activity','guard_event_material','guard_event_schedule','save_dossier_bundle','ticket_bot_operation'))
) as foundation_effects_catalog;
rollback;
